sys_script_fix.script:
function setProductTypeMandatory() {
	// Make product_type field mandatory on alm_license table

	new global.GlideQuery('sys_dictionary')
		.where('name', 'alm_license')
		.where('element', 'product_type')
		.updateMultiple({
			mandatory: true,
		});
}
setProductTypeMandatory();
